          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          // Определяем, нужно ли показывать кнопку «Показать ещё»
          bool _showMoreButton = false;
          void _checkHasMore() async {
            final currencyRepository = context.read<CurrencyRepository>();
            final CurrencyPage nextPage = await currencyRepository.fetchRates(CurrencyPageRequest(page: _currentPage));
            setState(() {
              _showMoreButton = nextPage.hasMore;
            });
          }

          // Проверяем наличие следующих страниц при загрузке и после каждого доп. запроса
          if (!_isLoadingMore) {
            _checkHasMore();
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_isLoadingMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          // Показываем индикатор загрузки при подгрузке следующей страницы
                          if (index >= data.length) {
                            return const Center(child: Padding(padding: EdgeInsets.all(16), child: CircularProgressIndicator()));
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, _showMoreButton ? 40 : 80),
                      );
                    },
                  ),
                ),
                if (_showMoreButton)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 16.0),
                    child: TextButton(
                      onPressed: _isLoadingMore ? null : _loadNextPage,
                      child: Text(context.loc.showMore),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}

